+  has(name: string): boolean {
+    return this.tools.has(name);
+  }
+
+  definitions(): McpFnToolDefinition<TContext>[] {
+    return [...this.tools.values()]
+      .map(({ definition }) => definition)
+      .sort((left, right) => left.name.localeCompare(right.name));
+  }
+
