+  if (!value || typeof value !== "object" || Array.isArray(value)) {
+    throw new McpFnValidationError("McpFn manifest must be an object");
+  }
+  const manifest = value as Partial<McpFnManifest>;
+  if (manifest.formatVersion !== 1) {
+    throw new McpFnValidationError("Unsupported McpFn manifest formatVersion");
+  }
+  if (
+    !manifest.server ||
+    typeof manifest.server.name !== "string" ||
+    typeof manifest.server.version !== "string"
+  ) {
+    throw new McpFnValidationError("Manifest server name and version are required");
+  }
+  if (!Array.isArray(manifest.tools)) {
+    throw new McpFnValidationError("Manifest tools must be an array");
+  }
+  const names = new Set<string>();
+  for (const tool of manifest.tools) {
+    if (!tool || typeof tool.name !== "string" || !tool.name) {
+      throw new McpFnValidationError("Every manifest tool requires a name");
+    }
+    if (names.has(tool.name)) {
+      throw new McpFnValidationError(`Duplicate manifest tool: ${tool.name}`);
+    }
+    names.add(tool.name);
+    if (typeof tool.description !== "string" || !tool.description.trim()) {
+      throw new McpFnValidationError(
+        `Manifest tool ${tool.name} requires a description`,
+      );
+    }
