+        annotations: { openWorldHint: false },
+        metadata: { "mcpfn/source": "langfn" },
+        handler: async (args) => {
+          const context: ToolContext = {
+            metadata: { transport: "mcp" },
+            policy: new ToolPolicy()
+          };
+          const result = await tool.run(args, context);
